=== FILE: apb_regs.v ===
`timescale 1ns/1ps
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements microarchitecture.md for interface_spec.md (requirement
// req-294155bac1). Zero wait states, no state machine; the only state is
// the four registers.
module apb_regs #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam integer NBYTES = DATA_WIDTH / 8;

    // Register file: four separate flops (microarchitecture section 2).
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    reg [DATA_WIDTH-1:0] reg0_d;
    reg [DATA_WIDTH-1:0] reg1_d;
    reg [DATA_WIDTH-1:0] reg2_d;
    reg [DATA_WIDTH-1:0] reg3_d;

    reg [DATA_WIDTH-1:0] rd_mux;

    // The one cycle in which the response is sampled and a write commits.
    wire       access = psel && penable;
    // Mapped: word aligned and inside 0x0..0xC (microarchitecture section 3).
    wire       mapped = (paddr[1:0] == 2'b00) &&
                        (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    wire       wr_en  = access && pwrite && mapped;
    wire       rd_en  = access && !pwrite && mapped;
    wire [1:0] idx    = paddr[3:2];

    // merge(old, data, strb): copy each byte of data whose strobe is set.
    function [DATA_WIDTH-1:0] merge;
        input [DATA_WIDTH-1:0] old_v;
        input [DATA_WIDTH-1:0] data;
        input [NBYTES-1:0]     strb;
        integer i;
        begin
            merge = old_v;
            for (i = 0; i < NBYTES; i = i + 1) begin
                if (strb[i]) begin
                    merge[8*i +: 8] = data[8*i +: 8];
                end
            end
        end
    endfunction

    // Next state.
    always @* begin
        reg0_d = reg0;
        reg1_d = reg1;
        reg2_d = reg2;
        reg3_d = reg3;
        if (wr_en) begin
            if (idx == 2'd0) reg0_d = merge(reg0, pwdata, pstrb);
            if (idx == 2'd1) reg1_d = merge(reg1, pwdata, pstrb);
            if (idx == 2'd2) reg2_d = merge(reg2, pwdata, pstrb);
            if (idx == 2'd3) reg3_d = merge(reg3, pwdata, pstrb);
        end
    end

    // State: synchronous, active-low reset to zero (microarchitecture section 5).
    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            reg0 <= reg0_d;
            reg1 <= reg1_d;
            reg2 <= reg2_d;
            reg3 <= reg3_d;
        end
    end

    // Read data: combinational 4:1 mux (microarchitecture section 4).
    always @* begin
        case (idx)
            2'd0:    rd_mux = reg0;
            2'd1:    rd_mux = reg1;
            2'd2:    rd_mux = reg2;
            default: rd_mux = reg3;
        endcase
    end

    assign prdata  = rd_en ? rd_mux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = access && !mapped;

`ifdef FORMAL
    // Design-intent properties (microarchitecture section 6). The decode
    // and byte merge here are written independently of mapped/merge above.
    // They are written for the default parameters.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    wire                    f_access = psel && penable;
    wire                    f_mapped = (paddr == 8'h00) || (paddr == 8'h04) ||
                                       (paddr == 8'h08) || (paddr == 8'h0c);
    wire [4*DATA_WIDTH-1:0] f_regs   = {reg3, reg2, reg1, reg0};

    // Manager assumptions: APB rules.
    always @(*) begin
        if (!f_past_valid) assume(!presetn);
        if (!presetn) assume(!psel);
        if (penable) assume(psel);
        if (psel && !pwrite) assume(pstrb == {NBYTES{1'b0}});
    end

    always @(posedge pclk) begin
        if (f_past_valid) begin
            // Setup is followed by access (zero wait states: one access cycle).
            if ($past(presetn) && $past(psel) && !$past(penable) && presetn)
                assume(psel && penable);
            // penable only directly after a setup phase.
            if (penable)
                assume($past(psel) && !$past(penable));
            // Request stable from setup through access.
            if (psel && penable) begin
                assume(paddr  == $past(paddr));
                assume(pwrite == $past(pwrite));
                assume(pwdata == $past(pwdata));
                assume(pstrb  == $past(pstrb));
            end
        end
    end

    // Response assertions.
    always @(*) begin
        assert(pready == 1'b1);
        if (!f_access) begin
            assert(prdata == {DATA_WIDTH{1'b0}});
            assert(pslverr == 1'b0);
        end else begin
            assert(pslverr == !f_mapped);
            if (!pwrite && f_mapped)
                assert(prdata == f_regs[paddr[3:2]*DATA_WIDTH +: DATA_WIDTH]);
            else
                assert(prdata == {DATA_WIDTH{1'b0}});
        end
    end

    // Registers are zero after reset.
    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn))
            assert(f_regs == {(4*DATA_WIDTH){1'b0}});
    end

    // Each byte of each register changes only in a mapped write access to
    // that register with its strobe set, and then to the written byte.
    genvar fk, fb;
    generate
        for (fk = 0; fk < 4; fk = fk + 1) begin : f_reg_chk
            for (fb = 0; fb < NBYTES; fb = fb + 1) begin : f_byte_chk
                always @(posedge pclk) begin
                    if (f_past_valid && $past(presetn)) begin
                        if ($past(psel && penable && pwrite && f_mapped &&
                                  (paddr[3:2] == fk) && pstrb[fb]))
                            assert(f_regs[fk*DATA_WIDTH + 8*fb +: 8] ==
                                   $past(pwdata[8*fb +: 8]));
                        else
                            assert(f_regs[fk*DATA_WIDTH + 8*fb +: 8] ==
                                   $past(f_regs[fk*DATA_WIDTH + 8*fb +: 8]));
                    end
                end
            end
        end
    endgenerate

    // Covers: the proof is not vacuous.
    always @(*) begin
        if (f_past_valid && presetn) begin
            cover(f_access && !pwrite && f_mapped && (paddr[3:2] == 2'd0) && (prdata != 0));
            cover(f_access && !pwrite && f_mapped && (paddr[3:2] == 2'd1) && (prdata != 0));
            cover(f_access && !pwrite && f_mapped && (paddr[3:2] == 2'd2) && (prdata != 0));
            cover(f_access && !pwrite && f_mapped && (paddr[3:2] == 2'd3) && (prdata != 0));
            cover(f_access && pwrite && f_mapped && (pstrb == 4'b0101));
            cover(f_access && pwrite && !f_mapped && pslverr);
            cover(f_access && !pwrite && !f_mapped && pslverr);
        end
    end
`endif

endmodule
=== END FILE ===
