`timescale 1ns/1ps
// Self-checking testbench for apb_regs (interface_spec.md section 7).
// Inputs are driven just after the falling edge and outputs are sampled
// 1 ns before the rising edge.
module apb_regs_tb;

    localparam integer AW = 8;
    localparam integer DW = 32;

    // Check tags, printed in failure messages.
    localparam integer T_SETUP = 10;  // 10: prdata, 11: pslverr in setup
    localparam integer T_IDLE  = 20;  // 20: prdata, 21: pslverr in idle
    localparam integer T_RESET = 30;  // 30: prdata, 31: pslverr in reset
    localparam integer T_READY = 40;  // pready in access
    localparam integer T_ERR   = 41;  // pslverr in access
    localparam integer T_RDATA = 42;  // prdata in read access

    reg             pclk;
    reg             presetn;
    reg  [AW-1:0]   paddr;
    reg             psel;
    reg             penable;
    reg             pwrite;
    reg  [DW-1:0]   pwdata;
    reg  [DW/8-1:0] pstrb;
    wire [DW-1:0]   prdata;
    wire            pready;
    wire            pslverr;

    apb_regs #(.ADDR_WIDTH(AW), .DATA_WIDTH(DW)) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    integer        passed;
    integer        failed;
    reg [8*64-1:0] nonce;
    reg [31:0]     model [0:3];
    reg [31:0]     rng;
    integer        i;
    integer        j;
    integer        n;
    reg [7:0]      r_a;
    reg [31:0]     r_d;
    reg [3:0]      r_s;
    reg            r_wr;

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // Watchdog: a hang is a failed run.
    initial begin
        #2000000;
        $fatal(1, "apb_regs_tb: watchdog timeout");
    end

    // ---------------------------------------------------------------- helpers
    function tb_mapped(input [7:0] a);
        begin
            tb_mapped = (a == 8'h00) || (a == 8'h04) || (a == 8'h08) || (a == 8'h0C);
        end
    endfunction

    function [7:0] reg_addr(input integer k);
        begin
            reg_addr = {4'h0, k[1:0], 2'b00};
        end
    endfunction

    task next_rand;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task check_eq(input [31:0] got, input [31:0] exp, input integer tag);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("apb_regs_tb: check %0d failed at %0t: got 0x%08h, expected 0x%08h (paddr=0x%02h pwrite=%0d pstrb=0x%01h)",
                       tag, $time, got, exp, paddr, pwrite, pstrb);
            end
        end
    endtask

    task check_quiet(input integer tag);
        begin
            check_eq(prdata, 32'h0000_0000, tag);
            check_eq({31'd0, pslverr}, 32'd0, tag + 1);
        end
    endtask

    task model_write(input [7:0] a, input [31:0] d, input [3:0] s);
        integer b;
        reg [31:0] tmp;
        begin
            if (tb_mapped(a)) begin
                tmp = model[a[3:2]];
                for (b = 0; b < 4; b = b + 1) begin
                    if (s[b]) tmp[8*b +: 8] = d[8*b +: 8];
                end
                model[a[3:2]] = tmp;
            end
        end
    endtask

    // One APB transfer: setup cycle, then one access cycle.
    // Called just after a falling edge; returns just after a falling edge.
    task apb_xfer(input wr, input [7:0] addr, input [31:0] wdata, input [3:0] strb,
                  input [31:0] exp_rdata, input exp_err);
        begin
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = wr;
            paddr   = addr;
            pwdata  = wdata;
            pstrb   = strb;
            #4;
            check_quiet(T_SETUP);
            @(negedge pclk);
            penable = 1'b1;
            #4;
            check_eq({31'd0, pready}, 32'd1, T_READY);
            check_eq({31'd0, pslverr}, {31'd0, exp_err}, T_ERR);
            if (!wr) check_eq(prdata, exp_rdata, T_RDATA);
            @(negedge pclk);
        end
    endtask

    task do_write(input [7:0] addr, input [31:0] data, input [3:0] strb);
        begin
            apb_xfer(1'b1, addr, data, strb, 32'h0000_0000, !tb_mapped(addr));
            model_write(addr, data, strb);
        end
    endtask

    task do_read(input [7:0] addr);
        begin
            apb_xfer(1'b0, addr, rng, 4'h0,
                     tb_mapped(addr) ? model[addr[3:2]] : 32'h0000_0000,
                     !tb_mapped(addr));
        end
    endtask

    task idle(input integer cycles);
        integer k;
        begin
            for (k = 0; k < cycles; k = k + 1) begin
                psel    = 1'b0;
                penable = 1'b0;
                pwrite  = rng[0];
                paddr   = rng[15:8];
                pwdata  = rng;
                pstrb   = rng[7:4];
                next_rand;
                #4;
                check_quiet(T_IDLE);
                @(negedge pclk);
            end
        end
    endtask

    task do_reset(input integer cycles);
        integer k;
        begin
            psel    = 1'b0;
            penable = 1'b0;
            presetn = 1'b0;
            for (k = 0; k < cycles; k = k + 1) begin
                paddr  = rng[15:8];
                pwdata = rng;
                pwrite = rng[1];
                pstrb  = rng[7:4];
                next_rand;
                #4;
                check_quiet(T_RESET);
                @(negedge pclk);
            end
            presetn = 1'b1;
            for (k = 0; k < 4; k = k + 1) model[k] = 32'h0000_0000;
        end
    endtask

    // ---------------------------------------------------------------- sequence
    initial begin
        passed = 0;
        failed = 0;
        nonce  = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};
        rng     = 32'h1234_5678;
        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'h00;
        pwdata  = 32'h0000_0000;
        pstrb   = 4'h0;
        for (i = 0; i < 4; i = i + 1) model[i] = 32'h0000_0000;

        @(negedge pclk);

        // 1. Reset, then the reset values, read back to back.
        do_reset(3);
        idle(1);
        for (i = 0; i < 4; i = i + 1) do_read(reg_addr(i));
        idle(1);

        // 2. Write every register with idle gaps, then read every register.
        do_write(8'h00, 32'hA5A5_0001, 4'hF);
        idle(2);
        do_write(8'h04, 32'h5A5A_0002, 4'hF);
        idle(1);
        do_write(8'h08, 32'hDEAD_BEEF, 4'hF);
        do_write(8'h0C, 32'hCAFE_F00D, 4'hF);
        idle(3);
        for (i = 0; i < 4; i = i + 1) do_read(reg_addr(i));
        idle(1);

        // 3. Walking ones and zeros on every register.
        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 32; j = j + 1) begin
                do_write(reg_addr(i), 32'h0000_0001 << j, 4'hF);
                do_read(reg_addr(i));
                do_write(reg_addr(i), ~(32'h0000_0001 << j), 4'hF);
                do_read(reg_addr(i));
            end
        end
        for (i = 0; i < 4; i = i + 1) do_read(reg_addr(i));
        idle(1);

        // 4. pstrb partial writes: every strobe pattern on every register.
        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                do_write(reg_addr(i), 32'h1122_3344, 4'hF);
                do_write(reg_addr(i), 32'hEEDD_CCBB, j[3:0]);
                do_read(reg_addr(i));
            end
        end
        idle(1);

        // 5. pstrb all zero: changes nothing, completes without error.
        do_write(8'h08, 32'h0BAD_0BAD, 4'h0);
        do_read(8'h08);
        idle(1);

        // 6. PSLVERR policy: every unmapped address, write and read.
        for (i = 0; i < 4; i = i + 1) do_write(reg_addr(i), 32'h0F0F_0000 | i, 4'hF);
        for (i = 0; i < 256; i = i + 1) begin
            r_a = i[7:0];
            if (!tb_mapped(r_a)) begin
                next_rand;
                do_write(r_a, rng, 4'hF);
                do_read({4'h0, r_a[3:2], 2'b00});  // aliased register unchanged
                do_read(r_a);
            end
        end
        for (i = 0; i < 4; i = i + 1) do_read(reg_addr(i));
        idle(2);

        // 7. Back-to-back mixed transfers.
        do_write(8'h00, 32'h0000_00AA, 4'hF);
        do_read(8'h00);
        do_write(8'h04, 32'h0000_BB00, 4'hF);
        do_write(8'h08, 32'h00CC_0000, 4'hF);
        do_read(8'h04);
        do_read(8'h08);
        do_read(8'h10);
        do_write(8'h0C, 32'hDD00_0000, 4'hF);
        do_read(8'h0C);
        do_write(8'h03, 32'hFFFF_FFFF, 4'hF);
        do_read(8'h00);
        idle(1);

        // 8. Pseudo-random traffic against the model.
        for (n = 0; n < 400; n = n + 1) begin
            next_rand;
            if (rng[4:2] < 3'd6) r_a = {4'h0, rng[1:0], 2'b00};
            else                 r_a = rng[15:8];
            r_wr = rng[5];
            next_rand;
            r_d = rng;
            next_rand;
            r_s = rng[3:0];
            if (r_wr) do_write(r_a, r_d, r_s);
            else      do_read(r_a);
            if (rng[10]) idle({30'd0, rng[9:8]});
        end
        for (i = 0; i < 4; i = i + 1) do_read(reg_addr(i));

        // 9. Reset again, straight after traffic.
        for (i = 0; i < 4; i = i + 1) do_write(reg_addr(i), 32'hFFFF_FFFF ^ i, 4'hF);
        do_reset(2);
        for (i = 0; i < 4; i = i + 1) do_read(reg_addr(i));
        idle(2);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
